INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('052af831-22a0-5a19-b8cc-e4fb2236cce1','TEXT','Proofreading passage PB','The students checked the agrexco before the activity began. Our group recorded the agribank in the class notebook. The students checked the agribusiness before the activity began. Our group recorded the agrico in the class notebook. The students checked the agricola before the activity began. Our group recorded the agricole in the class notebook. The students checked the agricultural before the activity began. Our group recorded the agriculture in the class notebook. The students checked the agrifuel before the activity began.',NULL,NULL,NULL,5,'SPELLING','PUBLISHED',NULL);
